(1756050, 239174, 20530, '<td valign="top">It looks like a cool clock; and fairly old, I''m guessing? Because it is shot straight-on the composition is symmetrical, and somewhat static. It also shows that the clock is not straight. I can''t say much more because it is so dark that most of the details are lost.</td>', 'It looks like a cool clock; and fairly old, I''m guessing? Because it is shot straight-on the composition is symmetrical, and somewhat static. It also shows that the clock is not straight. I can''t say much more because it is so dark that most of the details are lost.', '2005-10-03 15:30:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
