(1756055, 239408, 37320, '<td valign="top">Thats no fair!  Not all of us live next to the Lucky Charms factory ya know!!  Some of us have to take pictures of our rooms and stuff.</td>', 'Thats no fair!  Not all of us live next to the Lucky Charms factory ya know!!  Some of us have to take pictures of our rooms and stuff.', '2005-10-03 15:30:47.000000', NULL, 1),
(1756056, 237860, 37320, '<td valign="top">I tried to do a night shot and with all my efforts it didn''t turn out one quarter as good as this.</td>', 'I tried to do a night shot and with all my efforts it didn''t turn out one quarter as good as this.', '2005-10-03 15:31:32.000000', NULL, 1),
(1756064, 238964, 42100, '<td valign="top">Too many elements in this photo, confuses the eye.</td>', 'Too many elements in this photo, confuses the eye.', '2005-10-03 15:33:32.000000', NULL, 1),
(1756065, 238056, 37320, '<td valign="top">Really fits the challenge well in my opinion.</td>', 'Really fits the challenge well in my opinion.', '2005-10-03 15:33:38.000000', NULL, 1),
