(1756071, 237783, 37320, '<td valign="top">No fooling???  My corner is section 112!</td>', 'No fooling???  My corner is section 112!', '2005-10-03 15:35:18.000000', NULL, 1),
(1756073, 239528, 20530, '<td valign="top">That''s a pretty guppy and you caught it with nice sharp focus and good colors. I like the shallow DOF. IMO The tilt and crop of the glass detract from the compositon, as does the large white area at bottom.</td>', 'That''s a pretty guppy and you caught it with nice sharp focus and good colors. I like the shallow DOF. IMO The tilt and crop of the glass detract from the compositon, as does the large white area at bottom.', '2005-10-03 15:35:58.000000', NULL, 1),
(1756086, 239124, 37320, '<td valign="top">10 from me, most original and one of the best executed.</td>', '10 from me, most original and one of the best executed.', '2005-10-03 15:38:21.000000', NULL, 1),
(1756097, 237482, 20530, '<td valign="top">Wow, I''m curious to see if you entered the complementary colors challenge. Powerful color contrast. I''d love to see the original because I wonder if this isn''t a little heavily processed? If I''m wrong, that''s the most blindingly orange and blue sunset I''ve ever seen.</td>', 'Wow, I''m curious to see if you entered the complementary colors challenge. Powerful color contrast. I''d love to see the original because I wonder if this isn''t a little heavily processed? If I''m wrong, that''s the most blindingly orange and blue sunset I''ve ever seen.', '2005-10-03 15:44:04.000000', NULL, 1),
(1756113, 238127, 37961, '<td valign="top">This is really lovely. The focus, the way the tracks lead your eyes. Awesome..10.</td>', 'This is really lovely. The focus, the way the tracks lead your eyes. Awesome..10.', '2005-10-03 15:51:13.000000', NULL, 1),
