(1757804, 238793, 10985, '<td valign="top">Ah ça, c''est à Montréal. Original, comme photo de ton coin de pays.</td>', 'Ah ça, c''est à Montréal. Original, comme photo de ton coin de pays.', '2005-10-04 10:38:15.000000', NULL, 1),
(1757806, 237478, 42100, '<td valign="top">There is nice detail and contrast in the stadium, less of the uninteresting grass would help emphasize the stadium.  Horizons straight through the middle rarely look good. Try 2/3 stadium and 1/3 grass if you really want to keep the from the turf shot.</td>', 'There is nice detail and contrast in the stadium, less of the uninteresting grass would help emphasize the stadium.  Horizons straight through the middle rarely look good. Try 2/3 stadium and 1/3 grass if you really want to keep the from the turf shot.', '2005-10-04 10:40:09.000000', NULL, 1),
