INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1757950, 239227, 43565, '<td valign="top">I would like to see a little more of the bridge.</td>', 'I would like to see a little more of the bridge.', '2005-10-04 12:02:56.000000', NULL, 1),
(1757952, 239439, 43565, '<td valign="top">I would like this with a larger DOF.</td>', 'I would like this with a larger DOF.', '2005-10-04 12:04:38.000000', NULL, 1),
(1757957, 236520, 29474, '<td valign="top">While I do not like the subject of the photo, the lighting is really impressive.</td>', 'While I do not like the subject of the photo, the lighting is really impressive.', '2005-10-04 12:07:51.000000', NULL, 1),
(1757975, 238537, 40295, '<td valign="top">A view a bit more to the left might work better - it moves the orad aout of the center and the poles and wires would become less of a distraction.</td>', 'A view a bit more to the left might work better - it moves the orad aout of the center and the poles and wires would become less of a distraction.', '2005-10-04 12:22:52.000000', NULL, 1),
(1757985, 239363, 40295, '<td valign="top">The red in the center creates a focus fo me that then is in competition with the boat to the right so I end up unsure of hwt the focus of image is - and it does not come together as a unified whole for me.</td>', 'The red in the center creates a focus fo me that then is in competition with the boat to the right so I end up unsure of hwt the focus of image is - and it does not come together as a unified whole for me.', '2005-10-04 12:26:49.000000', NULL, 1),
(1757989, 239491, 40295, '<td valign="top">Can you move the structure out of the center of the image to give it a better composition?</td>', 'Can you move the structure out of the center of the image to give it a better composition?', '2005-10-04 12:27:48.000000', NULL, 1),
(1757997, 239295, 40295, '<td valign="top">To me it would look a bit better with more of the sky removed - say just above the base of the clouds - then I would try to add more on the right and left so the building and the hillside did not seem like they were crowed into the image.</td>', 'To me it would look a bit better with more of the sky removed - say just above the base of the clouds - then I would try to add more on the right and left so the building and the hillside did not seem like they were crowed into the image.', '2005-10-04 12:32:57.000000', NULL, 1),
(1758000, 239418, 11738, '<td valign="top">This could have been even better as a higher contrast black and white.</td>', 'This could have been even better as a higher contrast black and white.', '2005-10-04 12:34:18.000000', NULL, 1),
(1758004, 239352, 40295, '<td valign="top">Very good - I do feel that the shape of the clouds forced you to keep too much of the sky in the image.</td>', 'Very good - I do feel that the shape of the clouds forced you to keep too much of the sky in the image.', '2005-10-04 12:34:59.000000', NULL, 1),
(1758008, 237687, 11738, '<td valign="top">Awesome imnage treatment here.  I love it.</td>', 'Awesome imnage treatment here.  I love it.', '2005-10-04 12:35:34.000000', NULL, 1),
(1758017, 237293, 40295, '<td valign="top">I would corp out some on the left so that the rock ends up in the upper left third - where the rule of thirds lines intersect. You will still get enogh of the river to lead my view to the rock and the sky beyond. Taking out some but not all of the underbruch at the bottom would help as well.</td>', 'I would corp out some on the left so that the rock ends up in the upper left third - where the rule of thirds lines intersect. You will still get enogh of the river to lead my view to the rock and the sky beyond. Taking out some but not all of the underbruch at the bottom would help as well.', '2005-10-04 12:38:04.000000', NULL, 1),
