(1758870, 237879, 40019, '<td valign="top">Dreamy.  Nicely done.  Love the richness of the colors.</td>', 'Dreamy.  Nicely done.  Love the richness of the colors.', '2005-10-04 19:52:25.000000', NULL, 1),
(1758875, 238931, 40019, '<td valign="top">Cool!  Love the angle and symmetry of the bricks opening up to your main subjet. Very nice.</td>', 'Cool!  Love the angle and symmetry of the bricks opening up to your main subjet. Very nice.', '2005-10-04 19:55:17.000000', NULL, 1),
(1758876, 237694, 33481, '<td valign="top">WOW!!! I tried to photograph a lightining storm and out of 89 shots, I managed to capture one rod.  This is absolutely amazing.</td>', 'WOW!!! I tried to photograph a lightining storm and out of 89 shots, I managed to capture one rod.  This is absolutely amazing.', '2005-10-04 19:55:25.000000', NULL, 1),
