(1762313, 239127, 3554, '<td valign="top">Personally I don''t particularly like the color on his shirt. It draws my eye to one of the least important elements of the photo.</td>', 'Personally I don''t particularly like the color on his shirt. It draws my eye to one of the least important elements of the photo.', '2005-10-05 17:04:48.000000', NULL, 1),
(1762316, 238804, 42792, '<td valign="top">What can I say - simply meets the challenge beautifully.  Nice crisp shot too.</td>', 'What can I say - simply meets the challenge beautifully.  Nice crisp shot too.', '2005-10-05 17:05:17.000000', NULL, 1),
(1762322, 236791, 3554, '<td valign="top">Not much you could do about it, but I find the boat to distract from this shot. I might have cropped it out.</td>', 'Not much you could do about it, but I find the boat to distract from this shot. I might have cropped it out.', '2005-10-05 17:05:57.000000', NULL, 1),
(1762326, 238805, 42792, '<td valign="top">Tells a story.  Just wondered if non-colour version will make it more impactful.</td>', 'Tells a story.  Just wondered if non-colour version will make it more impactful.', '2005-10-05 17:07:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1762337, 239345, 3554, '<td valign="top">The composition of the blue in this shot really draws the eye. I like it.  :)</td>', 'The composition of the blue in this shot really draws the eye. I like it.  :)', '2005-10-05 17:10:07.000000', NULL, 1),
(1762340, 239403, 42792, '<td valign="top">Interesting find and great shot!  Is this a contemporary depiction of Viking sail?  Must be in Iceland or Denmark :).<br/> <br/>2nd look and really like it a lot.   Bumping it up to 9.</td>', 'Interesting find and great shot!  Is this a contemporary depiction of Viking sail?  Must be in Iceland or Denmark :). 2nd look and really like it a lot.   Bumping it up to 9.', '2005-10-05 17:10:41.000000', NULL, 1),
(1762343, 239425, 3554, '<td valign="top">I can really appreciate this one. You really caught the feel of a true Seattle commute!  Well done!</td>', 'I can really appreciate this one. You really caught the feel of a true Seattle commute!  Well done!', '2005-10-05 17:11:13.000000', NULL, 1),
(1762354, 238952, 42792, '<td valign="top">Just like the style a lot.  A tiny gripe: top left sky looks unrealistically too bright relative to the overall photo.</td>', 'Just like the style a lot.  A tiny gripe: top left sky looks unrealistically too bright relative to the overall photo.', '2005-10-05 17:13:35.000000', NULL, 1),
(1762355, 238484, 3554, '<td valign="top">Why is this upside down?</td>', 'Why is this upside down?', '2005-10-05 17:13:51.000000', NULL, 1),
(1762361, 239416, 42792, '<td valign="top">Just very eye-catching.  Nice colours against a pretty dramatic cloudy background.</td>', 'Just very eye-catching.  Nice colours against a pretty dramatic cloudy background.', '2005-10-05 17:15:46.000000', NULL, 1),
(1762368, 239124, 42792, '<td valign="top">Appropriate in keeping with the spirit of Tolkien.  Love the soft texture of the feather.  Have a soft spot for this being a fan of LOTR.</td>', 'Appropriate in keeping with the spirit of Tolkien.  Love the soft texture of the feather.  Have a soft spot for this being a fan of LOTR.', '2005-10-05 17:17:38.000000', NULL, 1),
(1762370, 239554, 10867, '<td valign="top">I love the colours, but I would have preferred the verticals to be vertical.</td>', 'I love the colours, but I would have preferred the verticals to be vertical.', '2005-10-05 17:18:09.000000', NULL, 1),
(1762374, 238931, 3554, '<td valign="top">Hey you''ve got one minute to submit!  :)</td>', 'Hey you''ve got one minute to submit!  :)', '2005-10-05 17:18:48.000000', NULL, 1),
(1762375, 237958, 10867, '<td valign="top">Very nice choice of perspective, but the blown out area are a bit bothersome.</td>', 'Very nice choice of perspective, but the blown out area are a bit bothersome.', '2005-10-05 17:19:23.000000', NULL, 1),
(1762378, 238977, 42792, '<td valign="top">A beautiful capture of a very beautiful animal.  Love her look.</td>', 'A beautiful capture of a very beautiful animal.  Love her look.', '2005-10-05 17:19:58.000000', NULL, 1),
(1762385, 239273, 10867, '<td valign="top">Sore areas are a bit overexposed, unfortunately.  Also, the small stip of sky at the top doesn''t seem to me to add to the image.  Cropping it off might have strengthened the photo.  Beautiful scene, though.</td>', 'Sore areas are a bit overexposed, unfortunately.  Also, the small stip of sky at the top doesn''t seem to me to add to the image.  Cropping it off might have strengthened the photo.  Beautiful scene, though.', '2005-10-05 17:22:05.000000', NULL, 1),
(1762387, 239031, 3554, '<td valign="top">This picture is a bit dull on the lighting and very cluttered. A shallower DoF might have helped or focusing in more on one element. Nothing is particularly eye catching or in focus.</td>', 'This picture is a bit dull on the lighting and very cluttered. A shallower DoF might have helped or focusing in more on one element. Nothing is particularly eye catching or in focus.', '2005-10-05 17:22:12.000000', NULL, 1),
(1762394, 237436, 42792, '<td valign="top">Had to bump this up.  Fabulous colors, all the more striking because of the simple foreground.</td>', 'Had to bump this up.  Fabulous colors, all the more striking because of the simple foreground.', '2005-10-05 17:24:45.000000', NULL, 1),
(1762395, 239448, 10867, '<td valign="top">Suggestion:  Crop the top to eliminate the little triangle of sky at the right.  Apart from that, this is a very nice image.</td>', 'Suggestion:  Crop the top to eliminate the little triangle of sky at the right.  Apart from that, this is a very nice image.', '2005-10-05 17:24:49.000000', NULL, 1),
(1762396, 239518, 3554, '<td valign="top">Try putting the main peak off center (to the right maybe?) There''s just not a lot to hold my interest in this particular composition. I like the subject you picked with the pathway and the mountains in the background. Waiting for the sun to set more (or being their earlier as the sun rose) might have given you more interesting lighting as well. Not a bad picture, just not a great one.</td>', 'Try putting the main peak off center (to the right maybe?) There''s just not a lot to hold my interest in this particular composition. I like the subject you picked with the pathway and the mountains in the background. Waiting for the sun to set more (or being their earlier as the sun rose) might have given you more interesting lighting as well. Not a bad picture, just not a great one.', '2005-10-05 17:25:04.000000', NULL, 1),
(1762399, 237879, 42792, '<td valign="top">Nice soft effect but not sure about the composition.</td>', 'Nice soft effect but not sure about the composition.', '2005-10-05 17:26:26.000000', NULL, 1),
(1762400, 238730, 3554, '<td valign="top">Unique take on the challenge - extra points for creativity.  :)</td>', 'Unique take on the challenge - extra points for creativity.  :)', '2005-10-05 17:26:42.000000', NULL, 1),
(1762403, 238797, 42792, '<td valign="top">Looks like it could be an illustration for a children''s book.  Nicely done.</td>', 'Looks like it could be an illustration for a children''s book.  Nicely done.', '2005-10-05 17:27:42.000000', NULL, 1),
(1762404, 238056, 10867, '<td valign="top">Hmmm.</td>', 'Hmmm.', '2005-10-05 17:27:47.000000', NULL, 1),
(1762411, 237714, 42792, '<td valign="top">Pretty awesome on color contrast!   Would make a great wall poster as it''s better viewed from a certain distance than up close.  Can''t help bumping it up.  Each time it draws me to have a second look.</td>', 'Pretty awesome on color contrast!   Would make a great wall poster as it''s better viewed from a certain distance than up close.  Can''t help bumping it up.  Each time it draws me to have a second look.', '2005-10-05 17:29:41.000000', NULL, 1),
(1762415, 239457, 42792, '<td valign="top">Pretty tones and textures.</td>', 'Pretty tones and textures.', '2005-10-05 17:30:33.000000', NULL, 1),
(1762416, 239352, 10867, '<td valign="top">Lovely!</td>', 'Lovely!', '2005-10-05 17:30:41.000000', NULL, 1),
(1762424, 238424, 42792, '<td valign="top">Looks a little over-exposed for my liking.  Good angle all the same.</td>', 'Looks a little over-exposed for my liking.  Good angle all the same.', '2005-10-05 17:32:00.000000', NULL, 1),
(1762441, 239418, 42792, '<td valign="top">Hmmm .. a bit undecided why I''m attracted to it without really liking it.  I think the effect looks a bit too much like it''s been \"created\" on purpose.</td>', 'Hmmm .. a bit undecided why I''m attracted to it without really liking it.  I think the effect looks a bit too much like it''s been \"created\" on purpose.', '2005-10-05 17:35:45.000000', NULL, 1),
(1762453, 238214, 10867, '<td valign="top">Very nice, but I''d have liked to see the top of the tower with a bit of breathing space over it.</td>', 'Very nice, but I''d have liked to see the top of the tower with a bit of breathing space over it.', '2005-10-05 17:37:12.000000', NULL, 1),
(1762459, 239499, 10867, '<td valign="top">I''m afraid that much of this image is overexposed.</td>', 'I''m afraid that much of this image is overexposed.', '2005-10-05 17:37:55.000000', NULL, 1),
(1762469, 239502, 10867, '<td valign="top">Very nice, except for the blue-magenta colour cast over the buildings.</td>', 'Very nice, except for the blue-magenta colour cast over the buildings.', '2005-10-05 17:39:59.000000', NULL, 1),
(1762477, 239342, 10867, '<td valign="top">Exposure problems.</td>', 'Exposure problems.', '2005-10-05 17:41:29.000000', NULL, 1),
(1762486, 237296, 42792, '<td valign="top">Seems a tad over-saturated and the left foreground of the bank is distracting.</td>', 'Seems a tad over-saturated and the left foreground of the bank is distracting.', '2005-10-05 17:44:08.000000', NULL, 1),
(1762537, 239550, 27421, '<td valign="top">Very striking.....7</td>', 'Very striking.....7', '2005-10-05 18:06:57.000000', NULL, 1),
(1762554, 237297, 41554, '<td valign="top">Very nice shot, excellent light and definition, but is it for the right challenge? Didn''t vote you down for that anyway, the pic is so good.</td>', 'Very nice shot, excellent light and definition, but is it for the right challenge? Didn''t vote you down for that anyway, the pic is so good.', '2005-10-05 18:15:45.000000', NULL, 1),
(1762629, 237482, 2170, '<td valign="top">composition seems very centered.  great colors, though.</td>', 'composition seems very centered.  great colors, though.', '2005-10-05 19:03:06.000000', NULL, 1),
(1762630, 237687, 2170, '<td valign="top">i like the dark tones in this quite a bit.</td>', 'i like the dark tones in this quite a bit.', '2005-10-05 19:03:19.000000', NULL, 1),
(1762631, 237783, 2170, '<td valign="top">this is a great shot...wonderful interpretation of the challenge.  i hope the advertising in the background worked and you shot this with a nikon :P</td>', 'this is a great shot...wonderful interpretation of the challenge.  i hope the advertising in the background worked and you shot this with a nikon :P', '2005-10-05 19:04:43.000000', NULL, 1),
(1762633, 239515, 2170, '<td valign="top">seems a little tilted to the right.  great idea, though.</td>', 'seems a little tilted to the right.  great idea, though.', '2005-10-05 19:05:33.000000', NULL, 1),
(1762634, 238032, 2170, '<td valign="top">i like the colors here quite a bit...very stunning.</td>', 'i like the colors here quite a bit...very stunning.', '2005-10-05 19:05:48.000000', NULL, 1),
(1762636, 238979, 2170, '<td valign="top">this is a great shot.  i''d like to see the composition lowered a little bit so that it includes everything here but still includes part of the sky above the barn.</td>', 'this is a great shot.  i''d like to see the composition lowered a little bit so that it includes everything here but still includes part of the sky above the barn.', '2005-10-05 19:06:49.000000', NULL, 1),
(1762639, 239498, 2170, '<td valign="top">fisheye, fisheye...roly poly fisheye.  great color.</td>', 'fisheye, fisheye...roly poly fisheye.  great color.', '2005-10-05 19:07:22.000000', NULL, 1),
(1762641, 239403, 2170, '<td valign="top">great tones here.  love the contrasts.</td>', 'great tones here.  love the contrasts.', '2005-10-05 19:07:58.000000', NULL, 1),
(1762642, 239199, 39243, '<td valign="top">Nice use of framing and perspective. 7</td>', 'Nice use of framing and perspective. 7', '2005-10-05 19:08:37.000000', NULL, 1),
(1762648, 238143, 39243, '<td valign="top">I am not sure how other members will view this photo but the capture with the woman jogging by excellent. THe shadows distract somewhat to the overall effect but nice none the less.</td>', 'I am not sure how other members will view this photo but the capture with the woman jogging by excellent. THe shadows distract somewhat to the overall effect but nice none the less.', '2005-10-05 19:11:11.000000', NULL, 1),
(1762650, 238804, 39243, '<td valign="top">nice use of space in your picture.</td>', 'nice use of space in your picture.', '2005-10-05 19:11:32.000000', NULL, 1),
(1762653, 237436, 39243, '<td valign="top">8</td>', '8', '2005-10-05 19:13:13.000000', NULL, 1),
(1762658, 238371, 39243, '<td valign="top">I have a picture much like this one. The recent fires were amazing and horrible.</td>', 'I have a picture much like this one. The recent fires were amazing and horrible.', '2005-10-05 19:15:04.000000', NULL, 1),
(1762662, 239483, 39243, '<td valign="top">spectacular reflection and colors. 8</td>', 'spectacular reflection and colors. 8', '2005-10-05 19:16:11.000000', NULL, 1),
(1762664, 238041, 39243, '<td valign="top">That is pretty cool  I wonder if you were in the same local as me for this photo? I was by Stoney Point.</td>', 'That is pretty cool  I wonder if you were in the same local as me for this photo? I was by Stoney Point.', '2005-10-05 19:17:24.000000', NULL, 1),
(1762668, 239425, 39243, '<td valign="top">I get what you are communicating but I fear for your score.</td>', 'I get what you are communicating but I fear for your score.', '2005-10-05 19:19:28.000000', NULL, 1),
(1762671, 239355, 31443, '<td valign="top">The sky is a little intensly blue but that´s how it is in Iceland, no half measures! Glæsileg mynd</td>', 'The sky is a little intensly blue but that´s how it is in Iceland, no half measures! Glæsileg mynd', '2005-10-05 19:20:41.000000', NULL, 1),
(1762707, 239513, 33982, '<td valign="top">rule #57) thou shall not put the horizon in the middle ofthe frame</td>', 'rule #57) thou shall not put the horizon in the middle ofthe frame', '2005-10-05 19:51:00.000000', NULL, 1),
(1762762, 238804, 3554, '<td valign="top">I like the use of negative space in your shot.</td>', 'I like the use of negative space in your shot.', '2005-10-05 20:27:54.000000', NULL, 1),
(1762796, 239437, 38032, '<td valign="top">very Ansel ...  the image is stunning.  Only criticism: composition is a 6 in my opinion and I get sorta lost in the midtones.  score: 7</td>', 'very Ansel ...  the image is stunning.  Only criticism: composition is a 6 in my opinion and I get sorta lost in the midtones.  score: 7', '2005-10-05 20:43:56.000000', NULL, 1),
(1762797, 239174, 38032, '<td valign="top">creepy - scary image. 6</td>', 'creepy - scary image. 6', '2005-10-05 20:44:27.000000', NULL, 1),
(1762802, 239147, 38032, '<td valign="top">really cool  -nice sepia fee. ... the dustiness is engaging and moody.  8</td>', 'really cool  -nice sepia fee. ... the dustiness is engaging and moody.  8', '2005-10-05 20:45:05.000000', NULL, 1),
(1762822, 238420, 32997, '<td valign="top">Evocative...lighting/shadow is beautiful!</td>', 'Evocative...lighting/shadow is beautiful!', '2005-10-05 20:55:40.000000', NULL, 1),
(1762834, 239384, 23877, '<td valign="top">NOT MANY OF THESES LEFT,WHAT STATE IS IT LOCATED IN.8</td>', 'NOT MANY OF THESES LEFT,WHAT STATE IS IT LOCATED IN.8', '2005-10-05 21:01:59.000000', NULL, 1),
(1762837, 239270, 23877, '<td valign="top">This area will look great this fall,nice capture of the rising fog.</td>', 'This area will look great this fall,nice capture of the rising fog.', '2005-10-05 21:04:16.000000', NULL, 1),
(1762847, 239276, 23877, '<td valign="top">Very Nice.10</td>', 'Very Nice.10', '2005-10-05 21:08:48.000000', NULL, 1),
(1762945, 238951, 11895, '<td valign="top">great sky, but the beach and the water are not that interesting; maybe cropping about a quarter to a third off the bottom would improve this shot</td>', 'great sky, but the beach and the water are not that interesting; maybe cropping about a quarter to a third off the bottom would improve this shot', '2005-10-05 21:38:47.000000', NULL, 1),
(1763002, 238486, 44151, '<td valign="top">I like the perspective and the aplshes of red. Excellent color balance.</td>', 'I like the perspective and the aplshes of red. Excellent color balance.', '2005-10-05 21:57:46.000000', NULL, 1),
(1763008, 239363, 3554, '<td valign="top">I like the red building, it''s an interesting subject but the rest of the picture (the buildings in the background, and the boat) don''t particularly add much to the shot. I do wonder what''s hanging off the red building though. So maybe a shot that isolated the red building more and perhaps let us see what''s hanging on the building might have been more captivating.</td>', 'I like the red building, it''s an interesting subject but the rest of the picture (the buildings in the background, and the boat) don''t particularly add much to the shot. I do wonder what''s hanging off the red building though. So maybe a shot that isolated the red building more and perhaps let us see what''s hanging on the building might have been more captivating.', '2005-10-05 21:59:42.000000', NULL, 1),
(1763016, 239221, 3554, '<td valign="top">I really love the color of her eyes and lips, but her face feels distorted and a closeup of her, for this challenge, seems rather dull. What might have made this interesting is if you had shot a picture of you and her doing something together, or maybe of her doing something. Some action would have told me more about her maybe. I think we all have people that are really important to us, so we could all have put up a portrait shot of someone we love, but does that really meet the challenge well?</td>', 'I really love the color of her eyes and lips, but her face feels distorted and a closeup of her, for this challenge, seems rather dull. What might have made this interesting is if you had shot a picture of you and her doing something together, or maybe of her doing something. Some action would have told me more about her maybe. I think we all have people that are really important to us, so we could all have put up a portrait shot of someone we love, but does that really meet the challenge well?', '2005-10-05 22:03:16.000000', NULL, 1),
(1763030, 239355, 3554, '<td valign="top">There''s nothing bad about this shot that I can put my finger on, but I also didn''t find a compelling reason to keep looking at it. I''m not quite sure what it is..maybe lack of contrast? Maybe the foreground? There''s a stronger picture here somewhere, especially with that brooding sky. I gave this a 5.</td>', 'There''s nothing bad about this shot that I can put my finger on, but I also didn''t find a compelling reason to keep looking at it. I''m not quite sure what it is..maybe lack of contrast? Maybe the foreground? There''s a stronger picture here somewhere, especially with that brooding sky. I gave this a 5.', '2005-10-05 22:05:41.000000', NULL, 1),
(1763049, 237879, 3554, '<td valign="top">This isn''t a bad shot but it feels very over-processed to me...I think it''s the colors in the foreground that all seem to run together. Maybe it''s just me but it feels like a painting more than a photo. The leaf in the upper right hand corner is pretty distracting, maybe try cropping it out?</td>', 'This isn''t a bad shot but it feels very over-processed to me...I think it''s the colors in the foreground that all seem to run together. Maybe it''s just me but it feels like a painting more than a photo. The leaf in the upper right hand corner is pretty distracting, maybe try cropping it out?', '2005-10-05 22:10:28.000000', NULL, 1),
(1763051, 237860, 38911, '<td valign="top">I love the richness &amp; feel of this photo!  Good job! <br/>(o: <br/> <br/></td>', 'I love the richness & feel of this photo!  Good job! (o:  ', '2005-10-05 22:11:10.000000', NULL, 1),
(1763055, 239438, 27421, '<td valign="top">Nice capture...7</td>', 'Nice capture...7', '2005-10-05 22:12:32.000000', NULL, 1),
(1763058, 239153, 38911, '<td valign="top">Im not a fan of flower pictures but I like what youve done here.  Good job! :o&gt;</td>', 'Im not a fan of flower pictures but I like what youve done here.  Good job! :o>', '2005-10-05 22:13:28.000000', NULL, 1),
(1763070, 237858, 38911, '<td valign="top">Youre sick I tell you  you need to get some help!<br/>7 for the effort!<br/></td>', 'Youre sick I tell you  you need to get some help!7 for the effort!', '2005-10-05 22:16:40.000000', NULL, 1),
(1763097, 238726, 3554, '<td valign="top">I like the title and the mood it portrays, but there''s something flat about this shot...maybe the lighting on his face and shirt? Or that there''s little depth to it (feels very flat).</td>', 'I like the title and the mood it portrays, but there''s something flat about this shot...maybe the lighting on his face and shirt? Or that there''s little depth to it (feels very flat).', '2005-10-05 22:22:15.000000', NULL, 1),
(1763198, 238805, 36619, '<td valign="top">if you could have cropped out some of the trash on the ground or maybe picked it up first this would have been really cool. it''s a great subject for a nostalgic shot. perhaps even trying it in black and white would have added some emotional quality. i really like the idea.</td>', 'if you could have cropped out some of the trash on the ground or maybe picked it up first this would have been really cool. it''s a great subject for a nostalgic shot. perhaps even trying it in black and white would have added some emotional quality. i really like the idea.', '2005-10-05 22:59:01.000000', NULL, 1),
(1763205, 239345, 36619, '<td valign="top">very dramatic image.</td>', 'very dramatic image.', '2005-10-05 23:01:33.000000', NULL, 1),
(1763248, 239349, 18339, '<td valign="top">Everything is beautiful in this picture but the sky lacks a little something</td>', 'Everything is beautiful in this picture but the sky lacks a little something', '2005-10-05 23:13:01.000000', NULL, 1),
(1763278, 237963, 11895, '<td valign="top">wonderful lighting, good capture</td>', 'wonderful lighting, good capture', '2005-10-05 23:21:54.000000', NULL, 1),
(1763326, 239548, 41574, '<td valign="top">Very attractive, clear shot.</td>', 'Very attractive, clear shot.', '2005-10-05 23:43:32.000000', NULL, 1),
(1763333, 238273, 16829, '<td valign="top">Nice light, but maybe the yellow enhanced a bit too much. And then, the eye doesn''t focus on any one Thing. Its a picture of everything; its a background.</td>', 'Nice light, but maybe the yellow enhanced a bit too much. And then, the eye doesn''t focus on any one Thing. Its a picture of everything; its a background.', '2005-10-05 23:45:18.000000', NULL, 1),
(1763347, 238588, 16829, '<td valign="top">Nicely framed, superb capture. I, for one, like the vgnetting effect here, whether or not it was in the lense. But I would have hoped for more crispness, more clarity of focus in the mountain. But sometimes the picture you want cant be grasped.</td>', 'Nicely framed, superb capture. I, for one, like the vgnetting effect here, whether or not it was in the lense. But I would have hoped for more crispness, more clarity of focus in the mountain. But sometimes the picture you want cant be grasped.', '2005-10-05 23:49:08.000000', NULL, 1),
(1763427, 239515, 675, '<td valign="top">i love this town...nice colors!</td>', 'i love this town...nice colors!', '2005-10-06 00:09:21.000000', NULL, 1),
(1763488, 238698, 675, '<td valign="top">i think you took away some of the impact by choosing to do it in b&amp;w...the city has so much rich color at night!</td>', 'i think you took away some of the impact by choosing to do it in b&w...the city has so much rich color at night!', '2005-10-06 00:33:19.000000', NULL, 1),
(1763491, 238753, 675, '<td valign="top">wow...awesome</td>', 'wow...awesome', '2005-10-06 00:35:31.000000', NULL, 1),
