(1764900, 238127, 40106, '<td valign="top">haha great titles!! I love the point of the tracks you chose to take the picture at the bend definitely adds to the pictures and almost gives it that "corner" feel!! awesome job 8</td>', 'haha great titles!! I love the point of the tracks you chose to take the picture at the bend definitely adds to the pictures and almost gives it that "corner" feel!! awesome job 8', '2005-10-06 14:30:54.000000', NULL, 1),
