INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1767857, 239258, 35804, '<td valign="top">This is just pure fun...plain and simple pure fun...very nice.</td>', 'This is just pure fun...plain and simple pure fun...very nice.', '2005-10-07 13:57:47.000000', NULL, 1),
(1767862, 239443, 35804, '<td valign="top">This has a really nice "nostalgic" aura about it...the "soft" works nice here...it compliments the lighting quite perfectly.</td>', 'This has a really nice "nostalgic" aura about it...the "soft" works nice here...it compliments the lighting quite perfectly.', '2005-10-07 13:59:36.000000', NULL, 1),
(1767868, 239535, 35804, '<td valign="top">I just love how light behaves within a city...the way it hides, the way it reflects, the way it dances and caresses...wonderful image.</td>', 'I just love how light behaves within a city...the way it hides, the way it reflects, the way it dances and caresses...wonderful image.', '2005-10-07 14:03:58.000000', NULL, 1),
(1767878, 238467, 35804, '<td valign="top">Sometimes a really miss living there...autumn is one of those times.</td>', 'Sometimes a really miss living there...autumn is one of those times.', '2005-10-07 14:05:41.000000', NULL, 1),
(1767889, 238956, 35804, '<td valign="top">...fantastic...the MANY contrasts...pure perfection...very well done.</td>', '...fantastic...the MANY contrasts...pure perfection...very well done.', '2005-10-07 14:08:37.000000', NULL, 1),
(1767896, 239459, 35804, '<td valign="top">Ohhhhhhhh! The kitty looks so sleepy, or maybe bored...a perfectly lovely protrait.</td>', 'Ohhhhhhhh! The kitty looks so sleepy, or maybe bored...a perfectly lovely protrait.', '2005-10-07 14:10:08.000000', NULL, 1),
(1767907, 239439, 35804, '<td valign="top">I really like this...the colors are just great, the softness, the subject...all comes together to make this lovely little bit of nostalgia.</td>', 'I really like this...the colors are just great, the softness, the subject...all comes together to make this lovely little bit of nostalgia.', '2005-10-07 14:14:26.000000', NULL, 1),
(1767908, 239487, 14603, '<td valign="top">I really like this..but then I`m not one of the "Partial desat haters" that seem to be abundant on DPC.<br/>I hope you haven`t been treated too harshly for your use of the technique.<br/>If you had kept the colour in the stalks and leaves between the two fence rails, that would have made this perfection for me...but it`s still very attention grabbing as is.<br/>Nicely done.</td>', 'I really like this..but then I`m not one of the "Partial desat haters" that seem to be abundant on DPC.I hope you haven`t been treated too harshly for your use of the technique.If you had kept the colour in the stalks and leaves between the two fence rails, that would have made this perfection for me...but it`s still very attention grabbing as is.Nicely done.', '2005-10-07 14:16:42.000000', NULL, 1),
(1767921, 238790, 14603, '<td valign="top">Unusual perspective which works quite well for me..it also suits the B/W  format.<br/>The picket fence and flag gives it a homely, little town feel.<br/>Good work.</td>', 'Unusual perspective which works quite well for me..it also suits the B/W  format.The picket fence and flag gives it a homely, little town feel.Good work.', '2005-10-07 14:21:41.000000', NULL, 1),
(1767931, 239302, 14603, '<td valign="top">A beautiful composition which has done good service to an equally beautiful area.<br/>Reminds me a lot of my part of the world.</td>', 'A beautiful composition which has done good service to an equally beautiful area.Reminds me a lot of my part of the world.', '2005-10-07 14:26:27.000000', NULL, 1),
(1767935, 239541, 14603, '<td valign="top">A beautiful subject for a painting. I like the way you have composed this..it really suits the panoramic format.</td>', 'A beautiful subject for a painting. I like the way you have composed this..it really suits the panoramic format.', '2005-10-07 14:28:07.000000', NULL, 1),
(1767948, 239228, 14603, '<td valign="top">The composition is superb and colours are fantastic, all that my eye wants is a subject to gaze on at the point where the leading lines from the polycovers and hedging converge.<br/>A silhouetted figure or a tractor disappearing into the distance and you would have a winner on your hands in my opinion.<br/>Still an eyecatching shot though.</td>', 'The composition is superb and colours are fantastic, all that my eye wants is a subject to gaze on at the point where the leading lines from the polycovers and hedging converge.A silhouetted figure or a tractor disappearing into the distance and you would have a winner on your hands in my opinion.Still an eyecatching shot though.', '2005-10-07 14:37:24.000000', NULL, 1),
(1767965, 239522, 14603, '<td valign="top">Very unusual..definitely thinking "outside the box" with this one.<br/>Works for me as an abstract. I like the way you have divided the image with colour, texture and light.</td>', 'Very unusual..definitely thinking "outside the box" with this one.Works for me as an abstract. I like the way you have divided the image with colour, texture and light.', '2005-10-07 14:45:11.000000', NULL, 1),
(1767971, 237436, 44275, '<td valign="top">This picture is beautiful. Seems like it was sharpened a little too much, but I still enjoy it.</td>', 'This picture is beautiful. Seems like it was sharpened a little too much, but I still enjoy it.', '2005-10-07 14:49:04.000000', NULL, 1),
(1767977, 237783, 14603, '<td valign="top">Nice "artistic" approach here.<br/>Concentrating on the handrail and letting the shallow DOF turn  the spectators into background interest is a complete reversal of what you would normally expect to see. It works well in my opinion as it is an unusual and fresh approach.<br/>Don`t know how it will fare with the DPC voters though..but I hope they are kind to you.</td>', 'Nice "artistic" approach here.Concentrating on the handrail and letting the shallow DOF turn  the spectators into background interest is a complete reversal of what you would normally expect to see. It works well in my opinion as it is an unusual and fresh approach.Don`t know how it will fare with the DPC voters though..but I hope they are kind to you.', '2005-10-07 14:55:49.000000', NULL, 1),
(1767979, 239425, 15574, '<td valign="top">This is one of those pictures I think that you "love" or you "hate". Cool perspective, I like this one. Good job.</td>', 'This is one of those pictures I think that you "love" or you "hate". Cool perspective, I like this one. Good job.', '2005-10-07 14:56:33.000000', NULL, 1),
(1767990, 239257, 44275, '<td valign="top">Excellent photo.</td>', 'Excellent photo.', '2005-10-07 15:06:06.000000', NULL, 1),
(1767997, 239131, 11738, '<td valign="top">Looks like you cropped highly from the original image or you sharpened too much.  there is definite halo-ing along that wire and street sign.</td>', 'Looks like you cropped highly from the original image or you sharpened too much.  there is definite halo-ing along that wire and street sign.', '2005-10-07 15:08:44.000000', NULL, 1),
(1768000, 239518, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2005-10-07 15:09:48.000000', NULL, 1),
(1768001, 238486, 4793, '<td valign="top">Nice composition and colors</td>', 'Nice composition and colors', '2005-10-07 15:10:15.000000', NULL, 1),
(1768057, 238725, 42005, '<td valign="top">Very thought provoking!  Unvelievably wonderful focus.  I like the alliteration and the messge.  Good luck with your photo. 10</td>', 'Very thought provoking!  Unvelievably wonderful focus.  I like the alliteration and the messge.  Good luck with your photo. 10', '2005-10-07 15:36:28.000000', NULL, 1),
(1768066, 239261, 42005, '<td valign="top">This photograph, besides being lovely to look at and well named, appears to be composed beautifully and evokes emotion.  It is a comforting feeling to me, as it puts me ''back to my idyllic childhood'' environment.   I love the stacks of straw in the background and wonder if it is a venue for hall hayrides.  The mustard is so plentiful and I want to pick some for a bouquet.</td>', 'This photograph, besides being lovely to look at and well named, appears to be composed beautifully and evokes emotion.  It is a comforting feeling to me, as it puts me ''back to my idyllic childhood'' environment.   I love the stacks of straw in the background and wonder if it is a venue for hall hayrides.  The mustard is so plentiful and I want to pick some for a bouquet.', '2005-10-07 15:40:38.000000', NULL, 1),
(1768068, 239433, 42005, '<td valign="top">PASSION.  MOVEMENT. EMOTION.  FEAR.  EXHILARATION. ANXIETY.<br/>Focus and movement blow me away too.  Great entry.</td>', 'PASSION.  MOVEMENT. EMOTION.  FEAR.  EXHILARATION. ANXIETY.Focus and movement blow me away too.  Great entry.', '2005-10-07 15:41:40.000000', NULL, 1),
(1768108, 239410, 42132, '<td valign="top">lovely shot,is it you?like the b&amp;w,and the "hidden "interior.looks like a great place to sit,wouldn''t mind joining you there!<br/></td>', 'lovely shot,is it you?like the b&w,and the "hidden "interior.looks like a great place to sit,wouldn''t mind joining you there!', '2005-10-07 16:13:26.000000', NULL, 1),
