INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1773765, 237879, 6870, '<td valign="top">I love this, Judy! Your ue of pp really emphasizes the misty beauty of this place and did wonderful things to your colors. Congratulations on a strong finish!</td>', 'I love this, Judy! Your ue of pp really emphasizes the misty beauty of this place and did wonderful things to your colors. Congratulations on a strong finish!', '2005-10-10 10:04:43.000000', NULL, 0),
