(1773769, 239302, 10413, '<td valign="top">Nice shot!  Congrats on placing 4th.<br/><br/><i>Message edited by author 2005-10-10 09:08:53.</i></td>', 'Nice shot!  Congrats on placing 4th.', '2005-10-10 10:07:41.000000', '2005-10-10 10:08:53.000000', 0),
(1773774, 239403, 10413, '<td valign="top">Congratulations on your 5th place and a very interesting shot.</td>', 'Congratulations on your 5th place and a very interesting shot.', '2005-10-10 10:10:01.000000', NULL, 0),
(1773777, 236666, 10413, '<td valign="top">Congrats Jason on another top 10.</td>', 'Congrats Jason on another top 10.', '2005-10-10 10:11:12.000000', NULL, 0),
(1773780, 238486, 10413, '<td valign="top">Love the fall colors in this one.  Congrats on a top ten finish.</td>', 'Love the fall colors in this one.  Congrats on a top ten finish.', '2005-10-10 10:11:53.000000', NULL, 0),
(1773783, 237879, 34058, '<td valign="top">I love this picture!  I do love  the filter that you used!  This is truly a dreamy picture!  Nicely done, and a great place, should have placed higher, but still a good placement!</td>', 'I love this picture!  I do love  the filter that you used!  This is truly a dreamy picture!  Nicely done, and a great place, should have placed higher, but still a good placement!', '2005-10-10 10:13:13.000000', NULL, 0),
(1773785, 238240, 10413, '<td valign="top">Congrats on a top 10 finish. I like how the water and the wood ramp both lead your eyes into the picture.</td>', 'Congrats on a top 10 finish. I like how the water and the wood ramp both lead your eyes into the picture.', '2005-10-10 10:14:16.000000', NULL, 0),
(1773788, 239257, 10413, '<td valign="top">Love this one.  Congrats on a nice finish.</td>', 'Love this one.  Congrats on a nice finish.', '2005-10-10 10:15:23.000000', NULL, 0),
